fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 5 {
            host::display::state_set(8 + i * 4, (80 + i * 70) * 8);
            host::display::state_set(9 + i * 4, (90 + (i % 3) * 100) * 8);
            host::display::state_set(10 + i * 4, 20 + i * 6);
            host::display::state_set(11 + i * 4, 34 - i * 7);
            i = i + 1;
        }
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(5);
    host::display::state_set(5, down);
    let tap: bool = down == 1 && prev == 0;
    let heat: bool = tap && host::display::pointer_y() < h / 2;
    let cool: bool = tap && host::display::pointer_y() >= h / 2;
    let mut hits: i32 = host::display::state_get(3);
    host::display::clear(0x0a0a0e);
    host::display::fill_rect(20, 20, w - 40, 2, 0x404050);
    host::display::fill_rect(20, h - 22, w - 40, 2, 0x404050);
    host::display::fill_rect(20, 20, 2, h - 40, 0x404050);
    host::display::fill_rect(w - 22, 20, 2, h - 40, 0x404050);
    let mut i: i32 = 0;
    while i < 5 {
        let b: i32 = 8 + i * 4;
        let mut x: i32 = host::display::state_get(b);
        let mut y: i32 = host::display::state_get(b + 1);
        let mut vx: i32 = host::display::state_get(b + 2);
        let mut vy: i32 = host::display::state_get(b + 3);
        if heat {
            vx = vx * 5 / 4;
            vy = vy * 5 / 4;
            if vx > 120 { vx = 120; }
            if vx < -120 { vx = -120; }
            if vy > 120 { vy = 120; }
            if vy < -120 { vy = -120; }
        }
        if cool {
            vx = vx * 3 / 4;
            vy = vy * 3 / 4;
        }
        x = x + vx;
        y = y + vy;
        if x < 26 * 8 { x = 26 * 8; vx = -vx; hits = hits + 1; }
        if x > (w - 26) * 8 { x = (w - 26) * 8; vx = -vx; hits = hits + 1; }
        if y < 26 * 8 { y = 26 * 8; vy = -vy; hits = hits + 1; }
        if y > (h - 26) * 8 { y = (h - 26) * 8; vy = -vy; hits = hits + 1; }
        host::display::state_set(b, x);
        host::display::state_set(b + 1, y);
        host::display::state_set(b + 2, vx);
        host::display::state_set(b + 3, vy);
        let sp: i32 = iabs(vx) + iabs(vy);
        let c: i32 = if sp > 60 { 0xff6040 } else if sp > 30 { 0xffc040 } else { 0x4080ff };
        host::display::fill_rect(x / 8 - 4, y / 8 - 4, 8, 8, c);
        i = i + 1;
    }
    if t % 90 == 0 {
        host::display::state_set(4, hits);
        hits = 0;
    }
    host::display::state_set(3, hits);
    host::display::draw_string(28, 28, "PRESSURE", 0x808080, 1);
    host::display::draw_number(110, 28, host::display::state_get(4), 0xffffff, 1);
    host::display::draw_string(28, h - 40, "TAP TOP=HEAT BOTTOM=COOL", 0x505050, 1);
    host::display::present();
}
